'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var floor = require( '@stdlib/math/base/special/floor' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var getDType = require( '@stdlib/ndarray/dtype' );
var getShape = require( '@stdlib/ndarray/shape' );
var getOrder = require( '@stdlib/ndarray/order' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var sliceTo = require( '@stdlib/ndarray/base/slice-to' );
var gcopy = require( '@stdlib/blas/base/gcopy' ).ndarray;
var baseZeros = require( '@stdlib/ndarray/base/zeros' );
var reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
var reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
var gscal = require( '@stdlib/blas/base/gscal' ).ndarray;
var contains = require( '@stdlib/array/base/assert/contains' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var base = require( './base.js' );


// VARIABLES //

var NORMS = [ 'backward', 'ortho', 'forward' ];


// MAIN //

/**
* Computes the one-dimensional discrete Fourier transform of a real-valued input ndarray and assigns the result to a provided output ndarray.
*
* @param {ndarrayLike} x - input ndarray
* @param {ndarrayLike} out - output ndarray
* @param {Options} [options] - function options
* @param {NonNegativeInteger} [options.n] - number of points over which to compute the transform
* @param {string} [options.normalize='backward'] - normalization mode
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {ndarrayLike} output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
* var zeros = require( '@stdlib/ndarray/zeros' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 4 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create an output ndarray:
* var out = zeros( [ 3 ], { 'dtype': 'complex128' } );
*
* // Perform operation:
* var v = rfftf( x, out );
* // returns <ndarray>[ <Complex128>[ 10.0, 0.0 ], <Complex128>[ -2.0, 2.0 ], <Complex128>[ -2.0, 0.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
function rfftf( x, out ) {
	var options;
	var norm;
	var view;
	var xdt;
	var odt;
	var sh;
	var M;
	var N;
	var n;
	var y;
	var s;

	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray-like object. Value: `%s`.', x ) );
	}
	if ( !isndarrayLike( out ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an ndarray-like object. Value: `%s`.', out ) );
	}
	norm = 'backward';
	xdt = getDType( x );
	odt = getDType( out );
	sh = getShape( x );
	N = sh[ 0 ];
	n = N;
	if ( arguments.length > 2 ) {
		options = arguments[ 2 ];
		if ( !isPlainObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		if ( hasOwnProp( options, 'n' ) ) {
			n = options.n;
			if ( !isNonNegativeInteger( n ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a nonnegative integer. Option: `%s`.', 'n', n ) );
			}
		}
		if ( hasOwnProp( options, 'normalize' ) ) {
			norm = options.normalize;
			if ( !contains( NORMS, norm ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be one of the following: "%s". Option: `%s`.', 'normalize', join( NORMS, '", "' ), norm ) );
			}
		}
	}
	M = floor( n/2 ) + 1;

	// When n differs from N, create a new input of length n:
	if ( n !== N ) {
		if ( n < N ) {
			// Create a view of the first n elements:
			x = sliceTo( x, [ n ], false, false );
		} else {
			// Create a new array of length n and copy the first N elements:
			y = baseZeros( xdt, [ n ], getOrder( x ) );
			gcopy( N, getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), 1, 0 ); // eslint-disable-line max-len
			x = y;
		}
	}
	// Compute the forward FFT:
	base( out, x );

	// Apply normalization:
	if ( norm !== 'backward' ) {
		if ( odt === 'complex128' ) {
			view = reinterpret128( getData( out ), 0 );
		} else {
			view = reinterpret64( getData( out ), 0 );
		}
		if ( norm === 'ortho' ) {
			s = 1.0 / sqrt( n );
		} else {
			s = 1.0 / n;
		}
		gscal( 2*M, s, view, 1, 0 );
	}
	return out;
}


// EXPORTS //

module.exports = rfftf;
